"use client"

import { Checkbox as CheckboxRoot, CheckboxIndicator } from "@ui-sdk/react/checkbox"
import { CheckIcon, MinusIcon } from "lucide-react"
import type * as React from "react"

import { cn } from "cn"

type CheckboxRootProps = React.ComponentProps<typeof CheckboxRoot>

type CheckboxProps = Omit<CheckboxRootProps, "onCheckedChange"> & {
  /** Shows the mixed state, as `checked="indeterminate"` does. A press still checks it. */
  indeterminate?: boolean
  /** A press gives `true` or `false`, so the handler keeps Base UI's boolean. */
  onCheckedChange?: (checked: boolean, details: Parameters<NonNullable<CheckboxRootProps["onCheckedChange"]>>[1]) => void
}

function Checkbox({ className, indeterminate, checked, onCheckedChange, ...props }: CheckboxProps) {
  return (
    <CheckboxRoot
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-input transition-colors outline-none group-has-disabled/field:opacity-50 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:not-data-checked:border-input after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:aria-checked:border-primary dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground group-has-[:focus-visible]/field-label:data-checked:border-primary dark:data-checked:bg-primary",
        className
      )}
      {...(indeterminate || checked !== undefined ? { checked: indeterminate ? "indeterminate" : checked } : {})}
      {...(onCheckedChange ? { onCheckedChange: (next, details) => onCheckedChange(next === true, details) } : {})}
      {...props}
    >
      <CheckboxIndicator className="grid place-content-center text-current transition-none [&>svg]:size-3.5">
        {(state) => (state.indeterminate ? <MinusIcon /> : <CheckIcon />)}
      </CheckboxIndicator>
    </CheckboxRoot>
  )
}

export { Checkbox }
